// Prompt 编辑器只保存纯文本与受控的 @图片 token；外部粘贴一律按 text/plain 写入，
// 避免浏览器把 Markdown/网页/代码片段转成不可编辑 HTML，或在同步时丢失换行与缩进。
function insertPlainTextAtSelection(text, editor){
    if(!editor) return false;
    const value = String(text ?? '').replace(/\r\n?/g, '\n');
    const selection = window.getSelection?.();
    const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
    if(!range || !editor.contains(range.commonAncestorContainer)){
        editor.appendChild(document.createTextNode(value));
        return true;
    }
    range.deleteContents();
    const fragment = document.createDocumentFragment();
    const lines = value.split('\n');
    lines.forEach((line, index) => {
        if(index) fragment.appendChild(document.createElement('br'));
        if(line) fragment.appendChild(document.createTextNode(line));
    });
    const lastNode = fragment.lastChild;
    range.insertNode(fragment);
    const nextRange = document.createRange();
    nextRange.setStartAfter(lastNode || editor.lastChild);
    nextRange.collapse(true);
    selection.removeAllRanges();
    selection.addRange(nextRange);
    return true;
}
function handlePromptPlainTextPaste(event){
    const editor = event.currentTarget;
    if(!editor || editor.getAttribute('contenteditable') === 'false') return;
    const text = event.clipboardData?.getData('text/plain');
    if(text == null) return;
    event.preventDefault();
    event.stopPropagation();
    insertPlainTextAtSelection(text, editor);
    editor.dispatchEvent(new Event('input', {bubbles:true}));
}
