    if(value === 'assets') { toggleAssetLibrary(true); return; }
    if(value === 'settings') { window.location.href = '/canvas-api-settings.html'; return; }
    const point = viewportCenter();
    let type = '';
    if(value === 'gpt') type = 'llm';
    else if(value === 'comfy') type = 'comfy';
    else if(value === 'enhance' || value === 'edit' || value === 'angle') type = 'comfy';
    else if(value === 'prompt' || value === 'online') type = 'generator';
    if(!type || !classicNodeDefinition(type)) return;
    const node = createClassicNode(type, point.x, point.y);
    if(!node) return;
    if(value === 'enhance') node.mode = 'enhance';
    if(value === 'edit') node.mode = 'edit';
    if(value === 'angle') node.title = '角度控制';
    if(value === 'online') node.title = '在线生图';
