            refs,
            compactMembers,
            ...single,
            width:Math.max(SMART_GROUP_MIN_WIDTH, Math.round(single.width + outerPad)),
            height:Math.max(SMART_GROUP_MIN_HEIGHT, Math.round(single.height + outerPad + summarySpace)),
            innerW:single.width,
