function canvasImageDragPayload(node, index=0){
    const img = node?.images?.[index];
    if(!img?.url) return null;
    return {url:img.url, name:img.name || node.title || 'image'};
}
// 迁移旧数据：早期把图片节点作为成员（items[]）放进分组的画布，统一把这些图片吸收进 group.images，
// 让它们显示为卡片内的缩略图网格（新模型）。一次性、幂等。
function migrateSmartGroupImageMembers(){
    let changed = false;
    nodes.filter(isSmartGroupNode).forEach(group => {
        const imageMemberIds = (Array.isArray(group.items) ? group.items : [])
            .map(id => nodes.find(n => n.id === id))
            .filter(m => m && isSmartImageNode(m) && (m.images || []).some(img => img?.url))
            .map(m => m.id);
        imageMemberIds.forEach(id => {
            const member = nodes.find(n => n.id === id);
            if(member && absorbImageNodeIntoSmartGroup(group, member)) changed = true;
        });
    });
    return changed;
}
async function loadCanvas(){
    try {
        rememberLastCanvasId(canvasId);
        const payload = window.LavansCanvasAdapter?.getWorkspace ? await window.LavansCanvasAdapter.getWorkspace(canvasId, sourceProjectId || 'default') : null;
        const workspace = payload?.workspace || {};
        canvas = {
            id:canvasId || 'lavans-smart-canvas',
            title:workspace.title || tr('canvas.smartCanvas'),
            icon:workspace.icon || 'sparkles',
            kind:workspace.kind || 'smart',
            project:workspace.project || sourceProjectId || 'default',
            owner:workspace.owner || '',
            color:workspace.color || '',
            pinned:Boolean(workspace.pinned),
            created_at:Number(workspace.created_at || 0),
            updated_at:Number(workspace.updated_at || 0),
            board_x:Number(workspace.board_x || 0),
            board_y:Number(workspace.board_y || 0),
            deleted_at:workspace.deleted_at || null,
            nodes:Array.isArray(workspace.nodes) ? workspace.nodes : [],
            connections:Array.isArray(workspace.connections) ? workspace.connections : [],
            viewport:workspace.viewport || {x:0,y:0,scale:1},
            logs:Array.isArray(workspace.logs) ? workspace.logs : [],
            settings:workspace.settings || {},
            agentRuns:Array.isArray(workspace.agentRuns) ? workspace.agentRuns : [],
            activeAgentRunId:workspace.activeAgentRunId || ''
        };
        rememberCanvasListProject(sourceProjectId || 'default');
        canvasUsesConnections = true;
        document.title = canvas.title;
        document.getElementById('smartTitle').textContent = canvas.title;
        nodes = canvas.nodes.map(normalizeLegacySmartNode).filter(Boolean);
        migrateSmartGroupImageMembers();
        canvas.connections = normalizeSmartConnections(canvas.connections || [], nodes);
        nodes.forEach(n => {
            if(n.type === 'smart-minimax') n.timelinePlaying = false;
            const pendingTasks = smartPendingTasks(n);
            if(pendingTasks.length){
                n.pending = Math.max(pendingTasks.length, Number(n.pending || 0) || pendingTasks.length);
                n.running = false;
            } else if(n.jimengPending) {
                n.pending = Math.max(1, Number(n.pending || 0) || 1);
                n.running = false;
            } else if(smartNodeHasDisplayResult(n)) {
                markSmartNodeComplete(n, {hideTimer:true});
            } else if(n.pending || n.queued) {
                clearSmartNodeBusyState(n);
            }
        });
        const cleanedCompletedState = clearCompletedNodeBusyStates();
        const recoveredLoopOutputs = recoverStuckLoopOutputsFromLogs();
        const hiddenCompletedTimers = hideCompletedRunTimers();
        const cleanedDetachedInputs = cleanupDetachedRunInputRefs();
        viewport = {...viewport, ...(canvas.viewport || {})};
        viewport.scale = safeScale(viewport.scale);
        if(canvas.settings) settings = {...settings, ...canvas.settings};
        normalizeSmartVideoModeSettings(settings, true);
        nodes.forEach(node => { if(node.runSettings) normalizeSmartVideoModeSettings(node.runSettings, true); });
        canvasDefaultSmartSettings = cloneSmartSettings(settings);
        loadRecentSmartSettings();
        updateProviderModels();
        applyViewport();
        render();
        if(cleanedDetachedInputs || cleanedCompletedState || recoveredLoopOutputs || hiddenCompletedTimers) scheduleSave();
        resumeSmartPendingTasks();
        resumeClassicPendingTasks();
        resumeJimengPendingNodes();
        renderSmartAgentDrawer();
    } catch(e) {
        toast(tr('smart.toastCanvasFail'));
    }
}
function scheduleSave(){
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveCanvas, 450);
}
async function saveCanvas(){
    if(!canvas) return;
    savePromptDraftForCurrent();
    nodes.forEach(node => {
        node.images = (node.images || []).map(img => mediaItemForStorage(stripImageGenerationMeta(img)));
        if(node.runSettings) node.runSettings = settingsForStorage(node.runSettings);
    });
    canvas.nodes = nodes;
    canvas.connections = normalizeSmartConnections(canvas.connections || [], nodes);
    canvas.settings = settingsForStorage(canvasDefaultSmartSettings || initialSmartSettings);
    canvas.viewport = {...viewport};
    const storageCanvas = canvasForStorage();
    canvasSyncInFlight = true;
    try {
        const payload = await window.LavansCanvasAdapter.saveWorkspace(storageCanvas, 'smart-canvas', canvasId, sourceProjectId || 'default', 'smart');
        const savedWorkspace = payload?.workspace || payload;
        if(savedWorkspace?.savedAt) canvas.savedAt = savedWorkspace.savedAt;
        if(savedWorkspace?.updated_at) canvas.updated_at = Number(savedWorkspace.updated_at);
    } catch(e) {
        console.warn('[SmartCanvas] workspace save failed:', e?.message || e);
        const remote = e?.payload?.detail?.canvas || e?.payload?.canvas;
        if(e?.status === 409 && remote){
            applyMergedServerCanvas(remote);
            canvas.updated_at = Number(remote.updated_at || canvas.updated_at || 0);
            toast('检测到其他窗口更新，已合并后重试保存');
            scheduleSave();
        } else if(Date.now() - lastCanvasSaveErrorAt > 5000){
            lastCanvasSaveErrorAt = Date.now();
            toast(`画布保存失败：${e?.message || '请稍后重试'}`);
        }
    } finally {
        canvasSyncInFlight = false;
    }
}
