function expandSmartPromptEditor(control, title='PROMPT', node=null){
    if(!promptExpandModal || !promptExpandInput || !control) return;
    smartPromptExpandTarget = control;
    // 优先取 promptDraftHtml（composer HTML，含 @ 提及），其次 node.text（原始 HTML），最后 textarea 纯文本
    const rawHtml = node?.promptDraftHtml || node?.text || (control.value ?? control.innerText ?? '');
    promptExpandInput.innerHTML = rawHtml;
    promptExpandModal.hidden = false;
    promptExpandModal.style.display = 'flex';
    promptExpandModal.classList.add('open');
    document.body.classList.add('prompt-expanded');
    requestAnimationFrame(() => promptExpandInput.focus());
}
function closeSmartPromptEditor(){
    if(!promptExpandModal) return;
    const target = smartPromptExpandTarget;
    if(target){
        const value = promptExpandInput.textContent || '';
        if('value' in target) target.value = value;
        else target.innerText = value;
        target.dispatchEvent(new Event('input', {bubbles:true}));
        target.dispatchEvent(new Event('change', {bubbles:true}));
    }
    smartPromptExpandTarget = null;
    promptExpandModal.hidden = true;
    promptExpandModal.style.display = 'none';
    promptExpandModal.classList.remove('open');
    document.body.classList.remove('prompt-expanded');
}
