        const grid = `<div class="smart-agent-media-receipt-grid">${mediaItems.map((item,index) => `<img class="smart-agent-media-receipt-thumb" src="${escapeAttr(item.url)}" alt="已生成图片 ${index + 1}，共 ${count} 张" loading="lazy" role="button" tabindex="0" data-agent-locate-node="${escapeAttr(toolRun?.nodeId || '')}">`).join('')}</div>`;
        return `<details class="smart-agent-media-receipt smart-agent-media-receipt-group is-image is-succeeded" data-agent-media-group="${escapeAttr(toolRun.id || '')}" data-agent-tool-run-id="${escapeAttr(toolRun?.id || '')}" data-agent-node-id="${escapeAttr(toolRun?.nodeId || '')}"${expanded ? ' open' : ''}><summary class="smart-agent-media-receipt-toggle"><span class="smart-agent-media-receipt-head"><span><i data-lucide="images"></i>${escapeHtml(label)}已生成 ×${count}</span><i class="smart-agent-media-receipt-chevron" data-lucide="chevron-right"></i></span>${stack}</summary>${grid}</details>`;
