    const roleClass = role === 'user' ? 'is-user' : role === 'assistant' ? 'is-assistant' : 'is-system';
    const kindLabels = {text:'消息',question:'确认',choice:'选择',document:'文档', 'tool-status':'运行状态',media:'媒体', 'cost-confirmation':'费用确认', 'final-receipt':'最终回执'};
    const kindIcons = {text:'message-circle',question:'list-checks',choice:'list-checks',document:'file-text','tool-status':'activity',media:'image','cost-confirmation':'receipt','final-receipt':'badge-check'};
    const roleLabels = {user:'您',assistant:'Lavans Agent',system:'系统',tool:'工具'};
