    if(smartAgentResponseBusy) turns.push('<article class="smart-agent-chat-turn is-assistant" data-agent-message-kind="tool-status"><div class="smart-agent-chat-turn-head"><span>Lavans Agent</span><strong>正在回复</strong></div><div class="smart-agent-chat-turn-body">正在理解这条消息；输入框仍可继续使用。</div></article>');
    if(smartAgentSessionBusy) turns.push('<article class="smart-agent-chat-turn is-system" data-agent-message-kind="tool-status"><div class="smart-agent-chat-turn-head"><span>对话状态</span><strong>正在恢复</strong></div><div class="smart-agent-chat-turn-body">正在从本机恢复这次 AgentSession…</div></article>');
    else if(smartAgentSessionError) turns.push(`<article class="smart-agent-chat-turn is-system" data-agent-message-kind="tool-status"><div class="smart-agent-chat-turn-head"><span>对话状态</span><strong>需要处理</strong></div><div class="smart-agent-chat-turn-body">${escapeHtml(smartAgentSessionError)}<small>系统不会静默切换模型或自动重发。</small></div></article>`);
