async function runSmartAgentShotVideoTask(runId, run, planNode, task, candidateNumber=1){
    let taskId = '';
    try {
        const images = [task.firstFrame,task.lastFrame].filter(item => item?.previewUrl).map((item,index) => ({referenceId:item.artifactVersionId || `${task.shotId}-${index}`,referenceIndex:index + 1,url:item.previewUrl,name:index === 0 ? '首帧' : '尾帧',role:index === 0 ? 'first_frame' : 'last_frame'}));
        const submitted = await smartAgentBackendRequest('/api/canvas-video', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:task.providerId,model:task.model,prompt:task.prompt,duration:task.outputDurationSeconds,aspect_ratio:task.ratio,resolution:task.resolution,images})});
        taskId = submitted.task_id;
        await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/attempts/register`, smartAgentReviewJsonOptions({planArtifactVersionId:planNode.artifactVersionId,videoTaskId:task.id,taskId}));
        await syncSmartAgentFoundationProjection(); render(); renderSmartAgentDrawer();
        const videos = await pollCanvasVideo(submitted.provider_id || task.providerId, taskId);
        const previewUrl = Array.isArray(videos) ? videos[0] : '';
        await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/attempts/record`, smartAgentReviewJsonOptions({planArtifactVersionId:planNode.artifactVersionId,videoTaskId:task.id,taskId,status:'succeeded',candidateNumber,previewUrl}));
        await syncSmartAgentFoundationProjection(); render();
        return true;
    } catch(error){
        const status = error?.smartTaskCancelled || smartAgentVisualBatchCancelled.has(runId) ? 'cancelled' : (error?.videoTaskTerminal ? 'failed' : 'interrupted');
        await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/attempts/record`, smartAgentReviewJsonOptions({planArtifactVersionId:planNode.artifactVersionId,videoTaskId:task.id,taskId,status,error:error?.message || ''})).catch(() => null);
        await syncSmartAgentFoundationProjection(); render();
        if(status === 'cancelled') throw error;
        return false;
    }
}
async function runSmartAgentShotVideoBatch(node){
    const run = smartAgentRunById(node.foundationRunId) || activeSmartAgentRun();
    const runId = run ? smartAgentReviewRunId(run) : node.foundationRunId;
    if(!runId) throw new Error('找不到对应的 AGENT 运行');
    smartAgentVisualBatchCancelled.delete(runId);
    const authorization = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/authorize`, smartAgentReviewJsonOptions({planArtifactVersionId:node.artifactVersionId}));
    await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/consume`, smartAgentReviewJsonOptions({planArtifactVersionId:node.artifactVersionId,authorizationId:authorization.authorization.authorizationId}));
    await syncSmartAgentFoundationProjection(); render(); renderSmartAgentDrawer();
    let succeeded = 0;
    for(const task of authorization.plan.tasks || []){
        if(smartAgentVisualBatchCancelled.has(runId)) throw smartTaskCancelledError();
        const candidateNumber = nodes.filter(item => item.agentFoundationProjection && item.foundationRunId === node.foundationRunId && item.artifactType === 'shot-video-candidate' && item.shotId === task.shotId && item.validityState === 'current').length + 1;
        if(await runSmartAgentShotVideoTask(runId, run, node, task, candidateNumber)) succeeded += 1;
    }
    const review = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/review/prepare`, smartAgentReviewJsonOptions({planArtifactVersionId:node.artifactVersionId}));
    await smartAgentFocusFoundationVersion(review.reviewArtifactVersionId);
    if(succeeded !== Number(authorization.plan.quantity || 0)) toast(`已有 ${succeeded} 个镜头成功；失败镜头已进入单独处理区，成功版本全部保留`);
    else toast('逐镜视频已生成，请逐镜播放、单选并审核；不会自动进入合成');
}
function smartAgentVideoRecoveryKey(node, shotId){ return `${node?.foundationRunId || ''}:${shotId || ''}`; }
function openSmartAgentShotVideoRecovery(node, shotId){
    smartAgentLegacyReadOnlyNotice();
    return;
    const group = (node?.shotVideoGroups || []).find(item => item.shotId === shotId);
    if(!group) throw new Error('找不到该镜头的恢复信息');
    smartAgentVideoRecoveryByShot.set(smartAgentVideoRecoveryKey(node, shotId), {open:true,mode:group.requiresPromptRevision ? 'policy' : 'retry',issueCodes:new Set(group.promptRevision?.issueCodes || []),preview:group.promptRevision || null,estimatedRetryCost:group.estimatedRetryCost,feeConfirmed:false,busy:false});
    renderSmartAgentDrawer();
}
async function previewSmartAgentShotVideoPromptRevision(node, shotId){
    smartAgentLegacyReadOnlyNotice();
    return;
    const key = smartAgentVideoRecoveryKey(node, shotId), state = smartAgentVideoRecoveryByShot.get(key);
    const group = (node?.shotVideoGroups || []).find(item => item.shotId === shotId);
    if(!state || !group) throw new Error('找不到该镜头的提示词修改区');
    if(!state.issueCodes?.size) throw new Error('请先勾选至少一个需要修改的方向');
    state.busy = true; smartAgentVideoRecoveryByShot.set(key, state); renderSmartAgentDrawer();
    try{
        const run = smartAgentRunById(node.foundationRunId) || activeSmartAgentRun();
        const runId = run ? smartAgentReviewRunId(run) : node.foundationRunId;
        const payload = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/prompt-revision/preview`, smartAgentReviewJsonOptions({planArtifactVersionId:node.planArtifactVersionId,videoTaskId:group.videoTaskId,shotId,issueCodes:[...state.issueCodes]}));
        state.preview = payload.revision; state.estimatedRetryCost = payload.estimatedRetryCost; state.feeConfirmed = false;
        if(payload.reviewArtifactVersionId) await smartAgentFocusFoundationVersion(payload.reviewArtifactVersionId);
        toast(payload.message || '提示词修改预览已建立');
    } finally { state.busy = false; smartAgentVideoRecoveryByShot.set(key, state); renderSmartAgentDrawer(); }
}
async function confirmSmartAgentShotVideoRecovery(node, shotId){
    smartAgentLegacyReadOnlyNotice();
    return;
    const key = smartAgentVideoRecoveryKey(node, shotId), state = smartAgentVideoRecoveryByShot.get(key);
    if(!state?.feeConfirmed) throw new Error('请先勾选确认本镜头的预计费用');
    const run = smartAgentRunById(node.foundationRunId) || activeSmartAgentRun();
    const runId = run ? smartAgentReviewRunId(run) : node.foundationRunId;
    let promptRevisionArtifactVersionId = '';
    if(state.mode === 'policy'){
        if(!state.preview?.artifactVersionId) throw new Error('请先生成并查看提示词修改预览');
        const confirmed = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/prompt-revision/confirm`, smartAgentReviewJsonOptions({planArtifactVersionId:node.planArtifactVersionId,promptRevisionArtifactVersionId:state.preview.artifactVersionId}));
        promptRevisionArtifactVersionId = confirmed.revision.artifactVersionId;
    }
    state.busy = true; smartAgentVideoRecoveryByShot.set(key, state); renderSmartAgentDrawer();
    try{ await retrySmartAgentShotVideo(node, shotId, {promptRevisionArtifactVersionId}); }
    finally { smartAgentVideoRecoveryByShot.delete(key); }
}
async function retrySmartAgentShotVideo(node, shotId, options={}){
    const run = smartAgentRunById(node.foundationRunId) || activeSmartAgentRun();
    const runId = run ? smartAgentReviewRunId(run) : node.foundationRunId;
    const planNode = nodes.find(item => item.agentFoundationProjection && item.foundationRunId === node.foundationRunId && item.artifactType === 'shot-video-production-plan' && item.validityState === 'current');
    const task = planNode?.shotVideoPlan?.tasks?.find(item => item.shotId === shotId);
    if(!planNode || !task) throw new Error('找不到该镜头的阶段九生产计划');
    const count = nodes.filter(item => item.agentFoundationProjection && item.foundationRunId === node.foundationRunId && item.artifactType === 'shot-video-candidate' && item.shotId === shotId).length;
    const retryBody = {planArtifactVersionId:planNode.artifactVersionId,videoTaskId:task.id,attemptNumber:Math.max(2,count + 1),promptRevisionArtifactVersionId:options.promptRevisionArtifactVersionId || ''};
    const authorization = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/retry/authorize`, smartAgentReviewJsonOptions(retryBody));
    await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/retry/consume`, smartAgentReviewJsonOptions({...retryBody,authorizationId:authorization.authorization.authorizationId}));
    await runSmartAgentShotVideoTask(runId, run, planNode, authorization.task || task, count + 1);
    const review = await smartAgentBackendRequest(`/api/canvas/agent-runs/${encodeURIComponent(runId)}/shot-videos/review/prepare`, smartAgentReviewJsonOptions({planArtifactVersionId:planNode.artifactVersionId}));
    await smartAgentFocusFoundationVersion(review.reviewArtifactVersionId);
    toast(`镜头 ${task.order} 已单独重做，其他镜头版本未改变`);
}
