        const title = ['smart-agent-stage','smart-agent-script-version','smart-agent-script-revision','smart-agent-approval-artifact'].includes(node.type) ? escapeHtml(node.title || 'AGENT 节点') : node.type === 'smart-group' ? (node.title === '万能分组' ? '智能分组' : (node.title || '智能分组')) : node.type === 'smart-prompt' ? 'Prompt' : node.type === 'smart-loop' ? 'Loop' : node.type === 'smart-minimax' ? 'MiniMax H3' : isClassic ? classicNodeTitle(node) : (imgs.length > 1 ? 'Group' : imgs.length ? 'Image' : escapeHtml(tr('smart.createImportNode')));
        const scale = nodeScale(node);
