    const groupId = createMenuGroupId;
    closeCreateMenu();
    let created = null;
    if(type === 'group'){
        const topLeft = nodeCreationTopLeft(p, {type:'smart-group', w:SMART_GROUP_DEFAULT_WIDTH, h:SMART_GROUP_DEFAULT_HEIGHT, images:[]});
        created = createSmartGroupNode(topLeft.x, topLeft.y);
    } else if(type === 'prompt'){
        const topLeft = nodeCreationTopLeft(p, {type:'smart-prompt', w:316, h:240, images:[]});
        created = createPromptNode(topLeft.x, topLeft.y);
    } else if(type === 'loop'){
        const topLeft = nodeCreationTopLeft(p, {type:'smart-loop', w:340, h:168, images:[]});
        created = createLoopNode(topLeft.x, topLeft.y);
    } else if(type === 'minimax' || type === 'smart-minimax'){
        const topLeft = nodeCreationTopLeft(p, {type:'smart-minimax', w:1040, h:640, images:[]});
        created = createMinimaxNode(topLeft.x, topLeft.y);
    } else if(classicNodeDefinition(type)){
        const definition = classicNodeDefinition(type);
        const topLeft = nodeCreationTopLeft(p, {type, w:definition.width, h:definition.height, images:[]});
        created = createClassicNode(type, topLeft.x, topLeft.y);
    } else {
        created = createImageNodeAt(p);
    }
