if(smartAgentResizeHandle){
    smartAgentResizeHandle.addEventListener('pointerdown', event => {
        if(event.button !== 0 || !smartAgentDrawerIsOpen || smartAgentDrawerViewportWidth() <= SMART_AGENT_DRAWER_MOBILE_BREAKPOINT) return;
        event.preventDefault();
        event.stopPropagation();
        smartAgentDrawerResizePointerId = event.pointerId;
        smartAgentResizeHandle.setPointerCapture?.(event.pointerId);
        shell?.classList.add('agent-drawer-resizing');
        document.body.classList.add('smart-agent-drawer-resizing');
    });
    smartAgentResizeHandle.addEventListener('pointermove', event => {
        if(event.pointerId !== smartAgentDrawerResizePointerId) return;
        event.preventDefault();
        event.stopPropagation();
        applySmartAgentDrawerWidth(smartAgentDrawerViewportWidth() - event.clientX, {remember:true});
    });
    smartAgentResizeHandle.addEventListener('pointerup', finishSmartAgentDrawerResize);
    smartAgentResizeHandle.addEventListener('pointercancel', finishSmartAgentDrawerResize);
    smartAgentResizeHandle.addEventListener('keydown', event => {
        if(smartAgentDrawerViewportWidth() <= SMART_AGENT_DRAWER_MOBILE_BREAKPOINT) return;
        const bounds = smartAgentDrawerBounds();
        let nextWidth = smartAgentDrawerWidth || bounds.defaultWidth;
        if(event.key === 'ArrowLeft') nextWidth += event.shiftKey ? 64 : 16;
        else if(event.key === 'ArrowRight') nextWidth -= event.shiftKey ? 64 : 16;
        else if(event.key === 'Home') nextWidth = bounds.min;
        else if(event.key === 'End') nextWidth = bounds.max;
        else return;
        event.preventDefault();
        event.stopPropagation();
        applySmartAgentDrawerWidth(nextWidth, {remember:true});
        persistSmartAgentDrawerWidth();
    });
}
