smartAgentQuestionOptions?.addEventListener('click', event => {
    const choice = event.target.closest('[data-agent-choice]');
    if(!choice) return;
    event.preventDefault();
    const value = choice.dataset.agentChoice || '';
    const question = currentSmartAgentInteractiveQuestion();
    const isMultiple = question?.type === 'multiple';
    let selectedValues = [];
    try { selectedValues = JSON.parse(smartAgentQuestionOptions.dataset.selectedValues || '[]'); }
    catch(_error){ selectedValues = []; }
    if(!Array.isArray(selectedValues)) selectedValues = [];
    if(isMultiple){
        const selecting = !selectedValues.includes(value);
        if(!selecting) selectedValues = selectedValues.filter(item => item !== value);
        else if(choice.dataset.agentExclusive === 'true') selectedValues = [value];
        else {
            const exclusiveValues = new Set([...smartAgentQuestionOptions.querySelectorAll('[data-agent-exclusive="true"]')].map(item => item.dataset.agentChoice || ''));
            selectedValues = [...selectedValues.filter(item => !exclusiveValues.has(item)), value];
        }
    } else {
        selectedValues = [value];
    }
    smartAgentQuestionOptions.dataset.selectedValues = JSON.stringify(selectedValues);
    smartAgentQuestionOptions.dataset.selectedValue = selectedValues[0] || '';
    smartAgentQuestionOptions.querySelectorAll('[data-agent-choice]').forEach(item => {
        const selected = selectedValues.includes(item.dataset.agentChoice || '');
        item.classList.toggle('is-selected', selected);
        item.setAttribute('aria-pressed', selected ? 'true' : 'false');
    });
    const needsCustom = selectedValues.includes('__custom__');
    if(smartAgentQuestionCustom){
        smartAgentQuestionCustom.hidden = !needsCustom;
        if(!needsCustom) smartAgentQuestionCustom.value = '';
        else smartAgentQuestionCustom.focus();
    }
    const structured = currentSmartAgentStructuredQuestion();
    if(structured){
        structured.draft.answers[question.id] = {questionId:question.id,values:selectedValues,customText:needsCustom ? String(smartAgentQuestionCustom?.value || '').trim() : '',skipped:false};
        smartAgentSaveStructuredQuestionDraft();
    }
    if(!isMultiple && value !== '__custom__'){
        if(structured) void advanceSmartAgentStructuredQuestion();
        else void advanceSmartAgentQuestionnaire();
    }
});
