smartAgentDrawer?.addEventListener('click', event => {
    const reviewCheck = event.target.closest?.('[data-agent-review-check]');
    if(reviewCheck){
        const node = selectedNode();
        if(node?.id){
            const remembered = new Set(smartAgentReviewChecksByNode.get(node.id) || []);
            const index = Number(reviewCheck.dataset.agentReviewCheck);
            if(!reviewCheck.checked) remembered.add(index);
            else remembered.delete(index);
            smartAgentReviewChecksByNode.set(node.id, remembered);
        }
    }
    const issue = event.target.closest?.('[data-agent-video-issue]');
    if(issue){
        const node = selectedNode(), key = smartAgentVideoRecoveryKey(node, issue.dataset.shotId), state = smartAgentVideoRecoveryByShot.get(key);
        if(state){
            state.issueCodes ||= new Set();
            if(issue.checked) state.issueCodes.add(issue.dataset.agentVideoIssue); else state.issueCodes.delete(issue.dataset.agentVideoIssue);
            state.preview = null; state.feeConfirmed = false; smartAgentVideoRecoveryByShot.set(key, state);
        }
    }
    const fee = event.target.closest?.('[data-agent-video-fee-confirm]');
    if(fee){
        const node = selectedNode(), key = smartAgentVideoRecoveryKey(node, fee.dataset.shotId), state = smartAgentVideoRecoveryByShot.get(key);
        if(state){ state.feeConfirmed = fee.checked; smartAgentVideoRecoveryByShot.set(key, state); }
    }
}, true);
