    const versionButton = event.target.closest('[data-agent-version-open]');
    if(versionButton){ event.preventDefault(); void openSmartAgentScriptVersion(versionButton.dataset.agentVersionOpen || ''); return; }
    const manualOpen = event.target.closest('[data-agent-script-manual]');
    if(manualOpen){
        event.preventDefault();
        smartAgentLegacyReadOnlyNotice();
        return;
    }
    if(event.target.closest('[data-agent-manual-cancel]')){ event.preventDefault(); if(smartAgentManualEditor) smartAgentManualEditor.hidden = true; return; }
    if(event.target.closest('[data-agent-manual-save]')){ event.preventDefault(); void submitSmartAgentManualVersion(); return; }
    if(event.target.closest('[data-agent-script-ai]')){ event.preventDefault(); void executeSmartAgentAiRevision(); return; }
    if(event.target.closest('[data-agent-script-submit]')){ event.preventDefault(); void submitSmartAgentScriptVersion(); return; }
    const cancelRevision = event.target.closest('[data-agent-revision-cancel]');
    if(cancelRevision){ event.preventDefault(); void cancelSmartAgentRevisionAttempt(cancelRevision.dataset.agentRevisionCancel || ''); return; }
    const preview = event.target.closest('[data-agent-material-preview]');
    if(preview){ event.preventDefault(); openSmartAgentMaterialPreview(preview.dataset.agentMaterialPreview || ''); return; }
    const remove = event.target.closest('[data-agent-material-remove]');
